	switch (selection) {
		case "nano_banana_2_1":
		case "nano_banana_2": return "gemini-nano-banana-2.1";
		case "nano_banana_2_lite": return "gemini-3.1-flash-lite-image";
		case "nano_banana_pro": return "gemini-3-pro-image";
		default: return;
	}
